/bin/bash -c "node -e '
const fs = require(\"fs\");
const path = require(\"path\");
const root = \"evals/files/workspace-dependencies\";
for (const tree of [\"base/packages\", \"packages\"]) {
  const base = path.join(root, tree);
  const packages = fs.readdirSync(base).sort();
  console.log(tree);
  for (const pkg of packages) {
    const manifest = JSON.parse(fs.readFileSync(path.join(base, pkg, \"package.json\"), \"utf8\"));
    const fields = [\"dependencies\", \"peerDependencies\", \"optionalDependencies\", \"devDependencies\"];
    console.log("'`  ${manifest.name}`);
    for (const field of fields) {
      const entries = Object.entries(manifest[field] || {});
      console.log(`    ${field}: ${entries.length ? entries.map(([name, spec]) => `${name} ${spec}`).join(", ") : "none"}`);
    }
  }
}
'"'"

